import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    opp_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')

    # If opponent has never defected, cooperate fully.
    if opp_def == 0:
        if n >= 95 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # If opponent has always defected, defect.
    if opp_def == n:
        return 'D'

    # Recent behavior analysis
    w = 10 if n >= 10 else n
    recent_op = op[-w:]
    recent_my = my[-w:]
    recent_opp_def = sum(1 for a in recent_op if a == 'D')
    recent_my_def = sum(1 for a in recent_my if a == 'D')

    # Track consecutive defections by opponent at end
    streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak += 1
        else:
            break

    # Track consecutive cooperations by opponent at end
    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            coop_streak += 1
        else:
            break

    # Late-game exploitation of a highly cooperative opponent
    if n >= 80:
        if opp_def <= max(1, n // 20):
            if rng.random() < 0.3:
                return 'D'

    # If opponent just defected
    if last_op == 'D':
        # If they've been mostly cooperative overall, forgive quickly
        if opp_def * 3 < n:
            if streak <= 1 and rng.random() < 0.6:
                return 'C'
            if streak >= 2 and rng.random() < 0.25:
                return 'C'
        # Sustained defection -> defect
        if streak >= 3:
            return 'D'
        if recent_opp_def >= 5:
            return 'D'
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent just cooperated
    # If they've been defecting a lot recently, punish
    if recent_opp_def >= 5:
        return 'D'
    if recent_opp_def >= 3:
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    # Exploit pattern: they cooperate often after our D? Otherwise cooperate.
    # If opponent has shown willingness to restore cooperation (coop streak), stay C
    if coop_streak >= 2:
        # occasional rare probe to test
        if n >= 30 and opp_def * 5 < n and rng.random() < 0.05:
            return 'D'
        return 'C'

    # If we defected last round and they cooperated -> they are forgiving; keep cooperating
    if last_my == 'D' and last_op == 'C':
        return 'C'

    # Default tit-for-tat-flavored: cooperate
    # Slight occasional testing early
    if n < 20 and rng.random() < 0.04:
        return 'D'

    return 'C'
